import{_ as t,c as s,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"筮宗原序","description":"周易辑闻 - 筮宗原序","frontmatter":{"title":"筮宗原序","description":"周易辑闻 - 筮宗原序"},"headers":[],"relativePath":"zh/classics/jiwen/010.md","filePath":"zh/classics/jiwen/010.md"}'),i={name:"zh/classics/jiwen/010.md"};function c(o,a,l,d,p,m){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"筮宗原序",tabindex:"-1"},[n("筮宗原序 "),e("a",{class:"header-anchor",href:"#筮宗原序","aria-label":"Permalink to “筮宗原序”"},"​")],-1),e("p",null,"神哉蓍乎！圣人所以决疑定志，明吉凶以成大业。斯兴治辅化之务，君子所当尽心，非卜史事也。圣人无惑，众人未能免惑，圣人不欲以己意解人之惑。天生神物以前，民用圣人托之。虽曰神道设教，非无是理，而矫诬斯世也。大极既判，气化而凝。寒暑之往来，三光之运烛，动者植者之荣瘁沔长，夫孰使然？必有妙于其间者。故祸福之至，有开必先，斯实然之理。若而吉，若而凶，曷去曷就，众人惑焉。圣人洞其几而发其缊，而神蓍告焉。是以事举而民信，业巨而名巍。若夫进德修业之君子，趋吉避凶之众人，莫不以之。嗟夫！有蓍道，道生于庖牺；有蓍用，用著于妫帝，而详于箕畴。筮有职，大宗伯率之；揲有法，大传明之；占有验，左氏传、国语可考也。孔圣没，错歇至唐，始有裔孙推明其法。幸经程子、朱子之正订，后学得讲求之。汝梅承先君子训，且俾博考先传，粗得其说，作筮宗。宗，聚也，筮之学聚此编也。抑尝谓「太极未判，则为阴为阳不可测，判则阴阳著矣。著未分，则为九六为七八未可辨，分则九六七八定矣。人心未动，则为吉为凶未可必，动则吉凶断矣。」方无思无为、寂然不动之时，吾心犹大极也，犹未分之蓍也。一有感焉，图存而亡兆，计安而危伏，固不待驷舌之追，措诸事业，而吉凶祸福已对立于胸中。是知吉凶界限，判于心动之初，居子必恐惧于不闻不睹，而致谨于喜怒哀乐之未发，使此心凝然湛焉，昭乎絜如，常若大极之未判，蓍策之未分，则天理全，人欲尽，念兹释兹，语默出处，皆纯乎道。夫如是，有不动，动斯吉；有不筮，筮斯神。此圣人心筮之妙，是为蓍筮之本。汴水赵汝梅叙。筮宗原序。",-1)])])}const h=t(i,[["render",c]]);export{f as __pageData,h as default};
